import java.util.*;

public class SolutionTest {
    public static void main(String[] args) {
        Map<Long, String> contributors = new LinkedHashMap<>();
        contributors.put(1L, "Ada");
        contributors.put(2L, "Grace");
        Map<Long, String> topics = new LinkedHashMap<>();
        topics.put(10L, "Java");
        topics.put(20L, "Testing");
        Map<Long, Solution.Article> articles = new LinkedHashMap<>();
        Solution.Catalog catalog = new Solution.Catalog(contributors, topics, articles);

        List<Long> contributorIds = new ArrayList<>(List.of(1L, 2L));
        List<Long> topicIds = new ArrayList<>(List.of(10L));
        Solution.Article created = Solution.create(catalog,
                new Solution.Article(100L, "First", contributorIds, topicIds));
        eq(100L, created.id());
        eq("First", created.title());
        eq(List.of(1L, 2L), created.contributorIds());
        eq(List.of(10L), created.topicIds());
        contributorIds.clear();
        topicIds.add(20L);
        eq(List.of(1L, 2L), Solution.read(catalog, 100L).contributorIds());
        eq(List.of(10L), Solution.read(catalog, 100L).topicIds());
        immutable(created.contributorIds());
        immutable(created.topicIds());

        expect(IllegalStateException.class, () -> Solution.create(catalog,
                new Solution.Article(100L, "Duplicate", List.of(1L), List.of(10L))));
        expect(NoSuchElementException.class, () -> Solution.read(catalog, 999L));

        List<Long> updatedContributors = new ArrayList<>(List.of(2L));
        List<Long> updatedTopics = new ArrayList<>(List.of(20L, 10L));
        Solution.Article updated = Solution.update(catalog, 100L, "Updated",
                updatedContributors, updatedTopics);
        eq(100L, updated.id());
        eq("Updated", updated.title());
        eq(List.of(2L), updated.contributorIds());
        eq(List.of(20L, 10L), updated.topicIds());
        updatedContributors.add(1L);
        updatedTopics.clear();
        eq(List.of(2L), Solution.read(catalog, 100L).contributorIds());
        eq(List.of(20L, 10L), Solution.read(catalog, 100L).topicIds());
        immutable(updated.contributorIds());
        immutable(updated.topicIds());

        expect(IllegalArgumentException.class,
                () -> Solution.update(catalog, 100L, "bad", List.of(99L), List.of(10L)));
        eq("Updated", Solution.read(catalog, 100L).title());
        expect(NoSuchElementException.class,
                () -> Solution.update(catalog, 999L, "x", List.of(1L), List.of(10L)));

        invalidCreate(catalog, new Solution.Article(0L, "x", List.of(1L), List.of(10L)));
        invalidCreate(catalog, new Solution.Article(-1L, "x", List.of(1L), List.of(10L)));
        invalidCreate(catalog, new Solution.Article(101L, " \t", List.of(1L), List.of(10L)));
        invalidCreate(catalog, new Solution.Article(101L, "x", List.of(), List.of(10L)));
        invalidCreate(catalog, new Solution.Article(101L, "x", List.of(1L), List.of()));
        invalidCreate(catalog, new Solution.Article(101L, "x", List.of(1L, 1L), List.of(10L)));
        invalidCreate(catalog, new Solution.Article(101L, "x", List.of(1L), List.of(10L, 10L)));
        invalidCreate(catalog, new Solution.Article(101L, "x", List.of(0L), List.of(10L)));
        invalidCreate(catalog, new Solution.Article(101L, "x", List.of(1L), List.of(-2L)));
        invalidCreate(catalog, new Solution.Article(101L, "x", List.of(99L), List.of(10L)));
        invalidCreate(catalog, new Solution.Article(101L, "x", List.of(1L), List.of(99L)));

        expect(NullPointerException.class, () -> Solution.create(null,
                new Solution.Article(101L, "x", List.of(1L), List.of(10L))));
        expect(NullPointerException.class, () -> Solution.create(catalog, null));
        expect(NullPointerException.class, () -> Solution.read(null, 100L));
        expect(NullPointerException.class,
                () -> Solution.update(catalog, 100L, null, List.of(1L), List.of(10L)));
        expect(NullPointerException.class, () -> Solution.delete(null, 100L));

        Solution.create(catalog, new Solution.Article(200L, "Second", List.of(1L), List.of(10L)));
        eq(List.of(100L, 200L), new ArrayList<>(articles.keySet()));
        check(Solution.delete(catalog, 100L), "existing article must be removed");
        check(!Solution.delete(catalog, 100L), "second deletion must return false");
        eq(List.of(200L), new ArrayList<>(articles.keySet()));
        eq(Map.of(1L, "Ada", 2L, "Grace"), contributors);
        eq(Map.of(10L, "Java", 20L, "Testing"), topics);
    }

    private static void invalidCreate(Solution.Catalog catalog, Solution.Article article) {
        expect(IllegalArgumentException.class, () -> Solution.create(catalog, article));
    }

    private static void immutable(List<Long> list) {
        expect(UnsupportedOperationException.class, () -> list.add(999L));
    }

    private static void eq(Object expected, Object actual) {
        if (!Objects.equals(expected, actual))
            throw new AssertionError("expected " + expected + " but got " + actual);
    }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void expect(Class<? extends Throwable> type, Runnable action) {
        try {
            action.run();
        } catch (Throwable t) {
            if (type.isInstance(t)) return;
            throw new AssertionError("expected " + type.getName() + " but got " + t, t);
        }
        throw new AssertionError("expected " + type.getName());
    }
}

